import 'package:equatable/equatable.dart';
class TripEntity extends Equatable {
 final int id; final String name,location,status,createdBy; final DateTime departureAt,returnAt; final int budget; final String? description,meetingPoint,bankCardNumber,bankAccountName; final String scheduleType; final List<String> costItems,rules; final int memberCount; final String leaderName; final bool isCreator,isMember,canJoin; final String? currentMemberStatus; final List<Map<String,dynamic>> members,departureOptions;
 const TripEntity({required this.id,required this.name,required this.location,required this.departureAt,required this.returnAt,required this.status,required this.budget,required this.createdBy,this.description,this.meetingPoint,this.bankCardNumber,this.bankAccountName,this.scheduleType='fixed',this.costItems=const [],this.rules=const [],this.memberCount=0,this.leaderName='کاربر هم‌سفر',this.isCreator=false,this.isMember=false,this.canJoin=true,this.currentMemberStatus,this.members=const [],this.departureOptions=const []});
 bool get isPreparing=>status=='preparing'; bool get canEdit=>isCreator; bool get isFixedSchedule=>scheduleType=='fixed';
 @override List<Object?> get props=>[id,name,location,departureAt,returnAt,status,budget,createdBy,description,meetingPoint,bankCardNumber,bankAccountName,scheduleType,costItems,rules,memberCount,leaderName,isCreator,isMember,canJoin,currentMemberStatus,members,departureOptions];
}